const ROTULOS_POR_PROVIDER: Readonly<Record<TipoProvider, RotulosDoProvider>> = {
  telegram: ROTULOS_TELEGRAM,
}

/**
 * Os rótulos do provedor ATIVO, com fallback 'telegram': um valor ausente ou
 * desconhecido cai no telegram — o único provedor real hoje (um campo
 * `provider` de outra onda nunca derruba o painel). Exportada para o teste
 * exercitar a escolha por provedor e o fallback sem montar React.
 */
export function rotulosDoProvider(provider?: TipoProvider | null): RotulosDoProvider {
  return provider === 'telegram' ? ROTULOS_POR_PROVIDER[provider] : ROTULOS_TELEGRAM
}

/**
 * Normaliza o campo `provider` do GET /telegram (OPCIONAL — o host ainda não o
 * emite) para um TipoProvider: só `'telegram'` passa; qualquer
 * outro valor (incl. `undefined`) cai no `'telegram'`. Exportada para o teste
 * exercitar o consumo do campo sem montar React.
 */
export function normalizarProvider(_valor: unknown): TipoProvider {
  return 'telegram'
}


/* ========================================================================== */
/* Render helpers (React puro, sem JSX)                                       */
/* ========================================================================== */

const h = React.createElement

type Children = React.ReactNode

function paragrafo(classe: string, ...filhos: Children[]): React.ReactNode {
  return h('p', { className: classe }, ...filhos)
}

/** O pontinho + texto de um chip de estado. */
function Chip({ chip }: { readonly chip: EstadoChip }): React.ReactNode {
  return h('span', { className: `guard-chip ${chip.tom === 'ok' ? 'guard-chip-success' : chip.tom === 'aviso' ? 'guard-chip-warning' : ''}` },
    h('span', { className: 'guard-chip-dot' }),
    chip.rotulo,
    chip.detalhe ? h('span', { className: 'guard-chip-handle' }, ` · ${chip.detalhe}`) : null,
  )
}

/** Um comando copiável (monospace + botão "copiar" com feedback). */
function LinhaDeComando({ bloco }: { readonly bloco: BlocoDeComando }): React.ReactNode {
  const [copiado, setCopiado] = useState(false)
  const copiar = async (): Promise<void> => {
    try {
      await navigator.clipboard.writeText(bloco.comando)
      setCopiado(true)
      window.setTimeout(() => setCopiado(false), 1200)
    } catch {
      setCopiado(false)
    }
  }
  return h('div', { className: 'guard-cmd-row' },
    h('code', { className: 'guard-code' }, bloco.comando),
    h('button', { type: 'button', className: 'guard-btn-sm', onClick: () => copiar(), 'data-guard-copy': '' },
      copiado ? 'copiado' : 'Copiar'),
    bloco.dica ? h('span', { className: 'guard-muted' }, bloco.dica) : null,
  )
}

/**
 * Um `<details>` progressivo-disclosure: o resumo verb-first e o corpo fica
 * dobrado até abrir. Usado no passo 1 ("Como criar o bot do zero"), no passo 3
 * ("E minha conversa?" e "Avançado") — regra painel: os detalhes não atravancam
 * o CTA único do estado.
 */
function Detalhes({
  resumo,
  aberto,
  aoAlternar,
  children,
}: {
  readonly resumo: React.ReactNode
  readonly aberto?: boolean
  readonly aoAlternar?: (aberto: boolean) => void
  readonly children: React.ReactNode
}): React.ReactNode {
  const props: Record<string, unknown> = {}
  if (aberto !== undefined) props['open'] = aberto
  if (aoAlternar !== undefined) {
    props['onToggle'] = (e: React.SyntheticEvent<HTMLDetailsElement>) => aoAlternar((e.target as HTMLDetailsElement).open)
  }
  return h('details', { className: 'guard-details', ...props },
    h('summary', { className: 'guard-details-summary', 'data-guard-detail': '' }, resumo),
    h('div', { className: 'guard-details-body' }, children),
  )
}

/**
 * O cabeçalho de um checkpoint aberto: "Passo N de 3 · <titulo>", com ✓ à frente
 * quando concluído. É O título do passo atual (só ele fica aberto).
 */
function CabecalhoPasso({
  indice,
  titulo,
  concluido,
}: {
  readonly indice: number
  readonly titulo: string
  readonly concluido: boolean
}): React.ReactNode {
  return h('span', { className: 'guard-card-title' },
    concluido ? h('span', { className: 'guard-step-check', 'aria-hidden': 'true' }, '✓') : null,
    `Passo ${indice} de 3 · ${titulo}`,
  )
}

/**
 * Um checkpoint CONCLUÍDO, colapsado (só título + resumo + um text-link de
 * acção, ex.: "Trocar") — a atenção vai ao único passo aberto. O `<indice>` e
 * o `<titulo>` não entram na linha fina (só o `✓` + resumo), para o painel
 * continuar escaneável.
 */
function PassoConcluido({
  resumo,
  aoAcao,
  rotuloAcao,
}: {
  readonly resumo: string
  readonly aoAcao?: () => void
  readonly rotuloAcao?: string
}): React.ReactNode {
  return h('div', { className: 'guard-card guard-step-done' },
    h('span', { className: 'guard-card-title' },
      h('span', { className: 'guard-step-check', 'aria-hidden': 'true' }, '✓'),
      resumo,
    ),
    aoAcao !== undefined && rotuloAcao !== undefined
      ? h('div', { className: 'guard-step-done-actions' },
          h('button', { type: 'button', className: 'guard-link', onClick: aoAcao }, rotuloAcao),
        )
      : null,
  )
}

/**
 * O conteúdo dobrado "Como criar o bot do zero" — os passos numerados do
 * @BotFather (progressive disclosure: não atravancam o campo de token).
 */
function BotaoBotFatherDetalhado({ rotulos }: { readonly rotulos: RotulosDoProvider }): React.ReactNode {
  return h('ol', { className: 'guard-botfather-steps' },
    rotulos.criacao.map((passo, i) => h('li', { className: 'guard-botfather-step', key: i }, passo)),
    h('li', { className: 'guard-botfather-step' }, rotulos.notaCriacao),
    h('li', { className: 'guard-botfather-step' }, rotulos.notaPrivado),
  )
}

/* ========================================================================== */
/* Cartão "Privacidade" — o bot é só para o dono                              */
/* ========================================================================== */

/**
 * As garantias de deny-by-default, em linguagem de dono. Cada item é coberto
 * por teste (auth.test.ts / core.test.ts: PAIR-005, PAIR-006, PAIR-007,
 * TG-007, TG-089) — este bloco só as mostra ao dono, não as implementa.
 */
const GARANTIAS_PRIVACIDADE: readonly string[] = [
  'Sem o código de pareamento (que só aparece neste painel), nenhum comando funciona — o bot recusa por omissão (default deny).',
  '/start responde apenas "Olá. Este bot é privado…" — boas-vindas inócuas, iguais para todos, sem parear ninguém.',
  'Comandos de estranhos são recusados em silêncio (nenhuma resposta na conversa) e contados na auditoria.',
  'Uma segunda parelha é recusada mesmo com um código válido: só existe UM dono, definido na primeira parelha.',
  'Tentativas erradas de /parear têm tetos (por conversa e globais) e um atraso crescente, para travar força bruta.',
]

/**
 * Os passos de remoção do username vivem nos rótulos do provedor ATIVO
 * (`rotulos.passosRemoverUsername` — ver o mapa "Rótulos por provedor"): no
 * telegram são os passos conservadores do /setusername (a documentação do
 * BotFather confirma que o comando `/setusername` é o ponto de edição/remoção
 * do `@username` — https://www.grambots.com/bots/botfather e
 * https://cnvrse.com/what-is-botfather).
 */

/**
 * O cartão "Privacidade" (renderizado SÓ quando configurado). Dois vértices:
 *  - A descoberta (encontrável vs não) NÃO usa o `handle` do token-state (que só
 *    vive em memória após um `POST /api/token`) — usa a rota `/api/privacidade`,
 *    que faz um `getMe` AO VIVO. Um bot só é encontrado na busca do Telegram SE
 *    tiver `@username`; sem ele desaparece.
 *  - O bloco de garantias deny-by-default é estático (coberto por testes).
 *
 * Estados:
 *  - `ok && handle`  → aviso "encontrável" + passos de remoção;
 *  - `ok && null`    → badge verde (getMe REAL confirmou sem username);
 *  - `!ok`           → neutro honesto + botão "Verificar de novo";
 *  - `estado === null` (ainda a carregar) → "verificando…".
 */
function CartaoPrivacidade({
  estado,
  rotulos,
  aoVerificar,
}: {
  readonly estado: EstadoPrivacidade | null
  readonly rotulos: RotulosDoProvider
  readonly aoVerificar: () => void
}): React.ReactNode {
  const titulo = h('span', { className: 'guard-card-title' }, 'Privacidade — só para você')

  const corpo =
    estado === null
      ? paragrafo('guard-intro', 'A verificar a descoberta do bot…')
      : estado.ok
        ? estado.handle !== null && estado.handle.length > 0
          ? h('div', { className: 'guard-privacy-body' },
              paragrafo('guard-intro', rotulos.encontravel.replaceAll('{handle}', estado.handle)),
              h('ol', { className: 'guard-botfather-steps' },
                rotulos.passosRemoverUsername.map((passo, i) => h('li', { className: 'guard-botfather-step', key: i }, passo)),
              ),
              paragrafo('guard-privacy-note', rotulos.semUsernameNota.replaceAll('{handle}', estado.handle)),
            )
          : h('div', { className: 'guard-privacy-body' },
              h('span', { className: 'guard-badge-ok' }, rotulos.naoEncontravel),
            )
        : h('div', { className: 'guard-privacy-body' },
            paragrafo('guard-intro', 'Não foi possível verificar agora (bot offline ou token inválido?).'),
            h('div', { className: 'guard-actions' },
              h('button', { type: 'button', className: 'guard-btn guard-btn-outline', onClick: aoVerificar },
                'Verificar de novo'),
            ),
          )

  return h('div', { className: 'guard-privacy-card' },
    titulo,
    corpo,
    h('div', { className: 'guard-privacy-block' },
      h('span', { className: 'guard-block-title' }, 'Se alguém achar o bot assim mesmo:'),
      h('ul', { className: 'guard-privacy-list' },
        GARANTIAS_PRIVACIDADE.map((g, i) => h('li', { className: 'guard-privacy-item', key: i }, g)),
      ),
    ),
  )
}

/**
 * O cartão "Privacidade" migra para o PASSO 3, dobrado num `<details>`
 * "E minha conversa?" — 1 linha de risco + 1 linha do que faz (texto EXATO do
 * contrato §3, provider-aware: `rotulos.ckpt3Conversas`), seguido do cartão AO
 * VIVO (getMe real decide o verde de "não encontrável" — NUNCA um verde
 * mentiroso) e das garantias deny-by-default.
 */
function CartaoPrivacidadeCkpt3(props: {
  readonly estado: EstadoPrivacidade | null
  readonly rotulos: RotulosDoProvider
  readonly aoVerificar: () => void
}): React.ReactNode {
  return h(Detalhes, { resumo: 'E minha conversa?' },
    paragrafo('guard-intro', props.rotulos.ckpt3Conversas),
    h(CartaoPrivacidade, { estado: props.estado, rotulos: props.rotulos, aoVerificar: props.aoVerificar }),
  )
}

/* ========================================================================== */
/* O pareamento VIA PAINEL                                                    */
/* ========================================================================== */

/**
 * O corpo do Passo 2 "Parear" — mostra o CTA "Gerar código" quando sem
 * pareamento, o CÓDIGO DE 6 DÍGITOS em caixa monospace espaçada + "Copiar", a
 * contagem `expira em m:ss` + "Gerar novo" e o status ao vivo "Aguardando…" →
 * "✓ Pareado" enquanto o dono digita. NUNCA `console.log` do código: ele só
 * vive neste state e no DOM.
 */
function CartaoParear(props: {
  readonly handle?: string
  readonly estado: EstadoDePareamentoUi
  readonly pareado: boolean
  readonly agora: number
  readonly rotulos: RotulosDoProvider
  readonly aoGerar: () => void
  readonly aoNovoCodigo: () => void
}): React.ReactNode {
  const [copiado, setCopiado] = useState(false)

  switch (props.estado.fase) {
    case 'gerando':
      return h('div', { style: { display: 'flex', flexDirection: 'column', gap: 10 } },
        paragrafo('guard-intro', 'A gerar o código…'),
      )
    case 'codigo': {
      const contagem = formatarContagem(props.estado.expiraEm, props.agora)
      const expirou = props.agora >= props.estado.expiraEm
      if (expirou) {
        return h('div', { className: 'guard-actions guard-col' },
          paragrafo('guard-error', 'Este código expirou. Gera um novo.'),
          h('button', { type: 'button', className: 'guard-btn guard-btn-primary', onClick: props.aoNovoCodigo },
            'Gerar novo código'),
        )
      }
      const digitoEspacado = espacarCodigo(props.estado.codigo)
      const copiar = async (): Promise<void> => {
        try {
          await navigator.clipboard.writeText(props.estado.codigo)
          setCopiado(true)
          window.setTimeout(() => setCopiado(false), 1200)
        } catch {
          setCopiado(false)
        }
      }
      return h('div', { className: 'guard-pair-body' },
        paragrafo('guard-intro', props.rotulos.naConversa),
        h('div', { className: 'guard-pair-step' },
          h('code', { className: 'guard-pair-code' }, digitoEspacado),
          h('button', { type: 'button', className: 'guard-btn-sm', onClick: () => void copiar(), 'data-guard-copy-code': '' },
            copiado ? 'copiado' : 'Copiar'),
        ),
        paragrafo('guard-code-line',
          props.rotulos.parearNoBot
            .replaceAll('{codigo}', props.estado.codigo)
            .replaceAll('{ref}', props.handle && props.handle.length > 0 ? `@${props.handle}` : 'o bot')),
        h('div', { className: 'guard-pair-countdown' },
          h('span', { className: 'guard-muted' }, `expira em ${contagem}`),
          h('button', { type: 'button', className: 'guard-btn-sm', onClick: props.aoNovoCodigo }, 'Gerar novo'),
        ),
        h('div', { className: 'guard-pair-status' },
          props.pareado
            ? h('span', { className: 'guard-chip guard-chip-success' },
                h('span', { className: 'guard-chip-dot' }),
                '✓ Pareado',
              )
            : h('span', { className: 'guard-chip' },
                h('span', { className: 'guard-chip-dot' }),
                'Aguardando…',
              ),
        ),
      )
    }
    case 'pareado':
      return h('div', { className: 'guard-pair-body' },
        h('span', { className: 'guard-chip guard-chip-success' },
          h('span', { className: 'guard-chip-dot' }),
          '✓ Pareado',
        ),
      )
    case 'expirou':
      return h('div', { className: 'guard-actions guard-col' },
        paragrafo('guard-error', 'Este código expirou. Gera um novo.'),
        h('button', { type: 'button', className: 'guard-btn guard-btn-primary', onClick: props.aoNovoCodigo },
          'Gerar novo código'),
      )
    case 'erro':
      return h('div', { className: 'guard-actions guard-col' },
        paragrafo('guard-error', props.estado.mensagem),
        h('button', { type: 'button', className: 'guard-btn guard-btn-outline', onClick: props.aoNovoCodigo },
          'Tentar de novo'),
      )
    default:
      // ocioso: CTA primário "Gerar código"
      return h('div', { className: 'guard-pair-body' },
        paragrafo('guard-intro',
          'Este painel gera um código de 6 dígitos só para ti. Tu envias esse código para o bot.'),
        h('div', { className: 'guard-actions' },
          h('button', { type: 'button', className: 'guard-btn guard-btn-primary', onClick: props.aoGerar },
            'Gerar código'),
        ),
      )
  }
}

/**
 * Espaça o código de 6 dígitos para exibição (`123456` → `1 2 3 4 5 6`) — a
 * caixa monospace espaçada ajuda a ler/copiar. O botão "Copiar" copia o código
 * CRU (sem espaços), porque o `/parear` espera os 6 dígitos juntos.
 */
function espacarCodigo(codigo: string): string {
  return codigo.split('').join(' ')
}

/* ========================================================================== */
/* O bloco "Agentes" — a lista de runs do dispatcher (Onda 6)                 */
/* ========================================================================== */

/**
 * O chip de status de UM run: pontinho + rotulo PT-BR. TONS: rodando =
 * neutro (a atencao vai para o que terminou), concluido = verde, falhou =
 * vermelho (o dono precisa de saber), cancelado = neutro.
 */
function ChipDeStatusDeAgente({ status }: { readonly status: StatusDeRun }): React.ReactNode {
  const extra = status === 'done' ? ' guard-chip-success' : status === 'failed' ? ' guard-chip-error' : ''
  return h('span', { className: `guard-chip${extra}` },
    h('span', { className: 'guard-chip-dot' }),
    rotuloDeStatus(status),
  )
}

/**
 * O bloco "🤖 Agentes" — abaixo da trilha. Espelha o /agentes e o
 * /parar-agente do bot: a lista de runs do HOST (id, skill, status PT-BR,
 * ha quanto tempo, resumo cortado) e o botao "Cancelar" por run ATIVO.
 *
 * Estados (fallback seguro: uma falha de fetch nunca quebra o painel):
 *  - ainda a carregar (null, sem erro)      → "A carregar os agentes…";
 *  - fetch falhou sem dados                 → a mensagem de erro;
 *  - lista vazia                            → o MESMO vazio do /agentes do
 *    bot: "Nenhum agente rodando.";
 *  - com runs                               → uma linha por run; o erro de um
 *    refresh falhado aparece em cima da lista (mantemos o ultimo resultado
 *    honesto, nunca um vazio inventado).
 */
function CartaoAgentes(props: {
  readonly estado: EstadoAgentes | null
  readonly erro: string | null
  readonly cancelandoId: string | null
  readonly agora: number
  readonly aoCancelar: (id: string) => void
}): React.ReactNode {
  const titulo = h('span', { className: 'guard-card-title' }, '🤖 Agentes')
  const notaDeErro = props.erro !== null ? paragrafo('guard-error', props.erro) : null

  const corpo =
    props.estado === null
      ? props.erro === null
        ? paragrafo('guard-intro', 'A carregar os agentes…')
        : h('div', { className: 'guard-agents-body' }, notaDeErro)
      : props.estado.runs.length === 0
        ? h('div', { className: 'guard-agents-body' },
            notaDeErro,
            paragrafo('guard-intro', 'Nenhum agente rodando.'),
          )
        : h('div', { className: 'guard-agents-body' },
            notaDeErro,
            h('ul', { className: 'guard-agents' },
              props.estado.runs.map((run) =>
                h('li', { className: 'guard-agent', key: run.id },
                  h('code', { className: 'guard-agent-id' }, run.id),
                  h('div', { className: 'guard-agent-body' },
                    h('div', { className: 'guard-agent-linha' },
                      h('span', { className: 'guard-agent-skill' }, run.skill),
                      h(ChipDeStatusDeAgente, { status: run.status }),
                      h('span', { className: 'guard-muted' }, formatarHaQuanto(run.startedAt, props.agora)),
                    ),
                    run.summary !== undefined && run.summary.length > 0
                      ? h('div', { className: 'guard-agent-summary' }, resumoExibido(run.summary))
                      : null,
                  ),
                  // O botao so existe para runs ATIVOS; o cancelar REDUZ
                  // exposicao e por isso nao pede confirmacao (CTL-024).
                  run.status === 'running'
                    ? h('button', {
                        type: 'button',
                        className: 'guard-btn-sm',
                        'data-guard-cancel-agent': run.id,
                        disabled: props.cancelandoId === run.id,
                        onClick: () => props.aoCancelar(run.id),
                      }, props.cancelandoId === run.id ? 'Cancelando…' : 'Cancelar')
                    : null,
                ),
              ),
            ),
          )

  return h('div', { className: 'guard-card' }, titulo, corpo)
}

/* ========================================================================== */
/* O cartão "Túnel" — o controle que voltou da home para as settings          */
/* ========================================================================== */

/**
 * Os textos EXATOS das três confirmações do túnel — preservados VERBATIM do
 * script do chrome antigo (`createClientScript`), porque a semântica de cada
 * uma já foi revisada (a de desligar desambigua: derruba o TÚNEL, não o DSH;
 * o bot e o painel — esta aba — ficam de pé).
 */
const TEXTO_CONFIRMACAO_TUNEL: Readonly<Record<'ligar' | 'desligar' | 'repor', string>> = Object.freeze({
  ligar: 'Ligar o túnel abre esta máquina à internet. Confirmar?',
  desligar: 'Desligar o TÚNEL? O DSH continua a correr em loopback; o bot e o painel não são afetados.',
  repor: 'Repor o estado de falha e voltar a desligado? (o túnel permanece desligado)',
})

/**
 * A caixa de confirmação do túnel — o MESMO padrão `guard-confirm` do
 * Avançado (texto vermelho + [Confirmar][Cancelar]). O Confirmar desabilita
 * enquanto a resposta não chega (anti-duplo-clique: o segundo POST morreria
 * em nonce inválido/expirado com um motivo enganador — mesmo porquê do
 * script antigo).
 */
function CartaoConfirmacaoTunel(props: {
  readonly acao: 'ligar' | 'desligar' | 'repor'
  readonly confirmando: boolean
  readonly aoConfirmar: () => void
  readonly aoCancelar: () => void
}): React.ReactNode {
  return h('div', { className: 'guard-card guard-confirm' },
    paragrafo('guard-error', TEXTO_CONFIRMACAO_TUNEL[props.acao]),
    h('div', { className: 'guard-actions' },
      h('button', {
        type: 'button',
        className: 'guard-btn guard-btn-primary',
        disabled: props.confirmando,
        onClick: props.aoConfirmar,
      }, props.confirmando ? 'a confirmar…' : 'Confirmar'),
      h('button', {
        type: 'button',
        className: 'guard-btn guard-btn-outline',
        disabled: props.confirmando,
        onClick: props.aoCancelar,
      }, 'Cancelar'),
    ),
  )
}

/**
 * O cartão "Túnel" — o espelho do controle que o chrome antigo injetava na
 * HOME do DSH, agora DENTRO da aba "Remote Access" das settings:
 *  - a PROJEÇÃO do estado (GET /state via o poll de ~5s): chip colorido pelo
 *    estado (READY verde, DEGRADED aviso, FAILED vermelho), URL SÓ em READY,
 *    countdown "expira em Xs" (o ticker `agora` de 1s do painel) e
 *    tentativas;
 *  - falha/nota em vermelho (guard-error) — texto do backend, sempre CHILDREN
 *    de React (a URL NUNCA é interpolada em HTML, doutrina do painel);
 *  - os TRÊS botões com a mesma habilitação do script antigo: Ligar só em
 *    STOPPED (2 etapas com nonce), Desligar em STARTING/READY/DEGRADED
 *    (confirmação, sem nonce), Repor SÓ em FAILED (2 etapas com nonce);
 *  - as instruções "como ligar o bot" (POST /telegram/click → passos) num
 *    bloco dobrado no fim do cartão.
 * Sem estado (503 `sem-estado` / ainda a carregar) o chip mostra "—" —
 * honesto: NUNCA um "desligado" inventado.
 */
function CartaoTunel(props: {
  readonly tunel: EstadoProjetado | null
  readonly agora: number
  readonly erro: string | null
  readonly emVoo: boolean
  readonly aoLigar: () => void
  readonly aoDesligar: () => void
  readonly aoRepor: () => void
  readonly passos: readonly PassoBot[] | null
  readonly passosAbertos: boolean
  readonly passosEmVoo: boolean
  readonly passosErro: string | null
  readonly aoPassos: () => void
  readonly aoAlternarPassos: (aberto: boolean) => void
}): React.ReactNode {
  const estado = props.tunel?.estado
  const titulo = h('span', { className: 'guard-card-title' }, 'Túnel')

  // O tom do chip segue a semântica do contrato: READY = operacional (verde),
  // DEGRADED = a re-tentar sozinho (aviso), FAILED = terminal, precisa de
  // ação humana (vermelho); os demais neutros.
  const tomChip =
    estado === 'READY'
      ? ' guard-chip-success'
      : estado === 'DEGRADED'
        ? ' guard-chip-warning'
        : estado === 'FAILED'
          ? ' guard-chip-error'
          : ''

  // A URL é texto puro como CHILDREN (nunca interpolada em atributo/HTML) e
  // só aparece em READY — o backend já a omite fora de READY, e a checagem
  // aqui é a segunda linha de defesa (o cliente não confia, verifica).
  const url =
    estado === 'READY' && typeof props.tunel?.url === 'string' && props.tunel.url.length > 0
      ? props.tunel.url
      : null

  const expira = linhaExpiraTunel(props.tunel?.expiraEm, props.agora)

  // falha.mensagem (FAILED/DEGRADED) ou nota de TTL expirado — em vermelho;
  // NUNCA os dois ao mesmo tempo (a falha tem precedência, como no script).
  const falha = props.tunel?.falha
  const mensagemFalha =
    falha !== null && falha !== undefined && typeof falha.mensagem === 'string' && falha.mensagem.length > 0
      ? falha.mensagem
      : typeof props.tunel?.nota === 'string' && props.tunel.nota.length > 0
        ? props.tunel.nota
        : null

  return h('div', { className: 'guard-card' },
    titulo,
    h('div', { className: 'guard-tunnel' },
      h('div', null,
        h('span', { className: `guard-chip${tomChip}` },
          h('span', { className: 'guard-chip-dot' }),
          rotuloDeEstadoTunel(estado),
        ),
      ),
      url !== null ? h('code', { className: 'guard-tunnel-url' }, url) : null,
      expira !== null ? paragrafo('guard-muted', expira) : null,
      props.tunel !== null
        ? paragrafo('guard-muted', `tentativas: ${String(props.tunel.tentativas)}`)
        : null,
      mensagemFalha !== null ? paragrafo('guard-error', mensagemFalha) : null,
      props.erro !== null ? paragrafo('guard-error', props.erro) : null,
      h('div', { className: 'guard-actions' },
        h('button', {
          type: 'button',
          className: 'guard-btn guard-btn-primary',
          disabled: props.emVoo || estado !== 'STOPPED',
          onClick: props.aoLigar,
        }, 'Ligar túnel'),
        h('button', {
          type: 'button',
          className: 'guard-btn guard-btn-outline',
          disabled: props.emVoo || !(estado === 'STARTING' || estado === 'READY' || estado === 'DEGRADED'),
          onClick: props.aoDesligar,
        }, 'Desligar túnel'),
        // FAILED só sai por reset humano (CTL-012) — o botão só acorda aí,
        // como no script antigo.
        h('button', {
          type: 'button',
          className: 'guard-btn guard-btn-outline',
          disabled: props.emVoo || estado !== 'FAILED',
          onClick: props.aoRepor,
        }, 'Repor (após falha)'),
      ),
      // Instruções "como ligar o bot" — o clique é um POST (escrita, com
      // CSRF) que devolve os passos do provedor ativo; os textos entram como
      // CHILDREN de React num <details> dobrado.
      h('div', { className: 'guard-tunnel-bot' },
        h('span', { className: 'guard-block-title' }, 'Como ligar o bot'),
        h('div', { className: 'guard-actions' },
          h('button', {
            type: 'button',
            className: 'guard-btn-sm',
            disabled: props.passosEmVoo,
            onClick: props.aoPassos,
          }, props.passosEmVoo ? 'A pedir…' : 'Ver instruções'),
        ),
        props.passosErro !== null ? paragrafo('guard-error', props.passosErro) : null,
        props.passos !== null
          ? h(Detalhes, {
              resumo: 'Passos',
              aberto: props.passosAbertos,
              aoAlternar: props.aoAlternarPassos,
            },
              props.passos.length === 0
                ? paragrafo('guard-intro', 'O servidor não devolveu passos.')
                : props.passos.map((passo, i) =>
                    h('div', { className: 'guard-tunnel-passo', key: i },
                      h('p', { className: 'guard-tunnel-passo-titulo' }, passo.titulo),
                      h('p', { className: 'guard-tunnel-passo-texto' }, passo.texto),
                    ),
                  ),
            )
          : null,
      ),
    ),
  )
}

/* ========================================================================== */
/* O PAINEL — a section `settings.section`                                    */
/* ========================================================================== */

/**
 * Conteúdo da aba "Remote Access". Dados vêm do backend via fetch; o painel
 * re-busca ao montar e a cada ~5s (mais em `focus`/`visibilitychange`).
 */
function TelegramGuardSection(): React.ReactNode {
  const [token, setToken] = useState<EstadoDoToken | null>(null)
  // O estado AO VIVO do bot (GET /telegram): online/offline + motivo/handle —
  // alimenta o chip do cabeçalho. `null` = ainda a carregar (ou fetch falhou e
  // mantemos o último resultado honesto).
  const [telegrama, setTelegrama] = useState<EstadoTelegrama | null>(null)
  // O provedor de mensageria ATIVO (campo `provider` do GET /telegram —
  // OPCIONAL: o host ainda não o emite; o default 'telegram' cobre a
  // paridade que vem na onda do host).
  const [provider, setProvider] = useState<TipoProvider>('telegram')
  const [tokenErro, setTokenErro] = useState<string | null>(null)
  // A checagem AO VIVO de descoberta (GET /api/privacidade); `null` = ainda a
  // carregar (ou o fetch falhou e mantemos o último resultado honesto).
  const [privacidade, setPrivacidade] = useState<EstadoPrivacidade | null>(null)
  // A lista de AGENTES (GET /agents); `null` = ainda a carregar. Em falha de
  // fetch mantemos o último resultado honesto e anotamos o erro em baixo.
  const [agentes, setAgentes] = useState<EstadoAgentes | null>(null)
  const [agentesErro, setAgentesErro] = useState<string | null>(null)
  // O id do run cujo cancelamento está em voo (o botão mostra "Cancelando…").
  const [cancelandoId, setCancelandoId] = useState<string | null>(null)

  // A PROJEÇÃO do túnel (GET /state); `null` = ainda a carregar OU o 503
  // `sem-estado` (nenhuma difusão chegou) — em ambos o cartão mostra "—",
  // nunca um estado inventado. Em falha de rede mantemos o último resultado
  // honesto (o mesmo padrão do cartão de privacidade).
  const [tunel, setTunel] = useState<EstadoProjetado | null>(null)
  // O erro de POST do túnel (motivo do 409, rede, CSRF) — linha vermelha no
  // cartão. Limpo a cada nova ação.
  const [tunelErro, setTunelErro] = useState<string | null>(null)
  // Um POST do túnel (passo 1 de LIGAR/REPOR) em voo — desabilita os três
  // botões para não lançar dois intents com o mesmo estado na tela.
  const [tunelEmVoo, setTunelEmVoo] = useState(false)
  // A ação pendente da caixa guard-confirm do túnel ('ligar'/'desligar'/
  // 'repor') — estado PRÓPRIO, separado da confirmação do Avançado, porque o
  // fluxo do túnel carrega nonce e guarda anti-duplo-clique próprios.
  const [confirmacaoTunel, setConfirmacaoTunel] = useState<'ligar' | 'desligar' | 'repor' | null>(null)
  // Anti-duplo-clique do botão Confirmar (o MESMO porquê do script antigo:
  // dois POSTs com o MESMO nonce — o segundo morreria em nonce inválido).
  const [confirmandoTunel, setConfirmandoTunel] = useState(false)
  // O nonce do LIGAR/REPOR entre o passo 1 e o passo 2 — OPACO: o cliente não
  // o lê nem o valida, só o devolve no passo 2 (S5; quem valida é o host).
  const nonceTunelRef = useRef<string | null>(null)

  // As instruções "como ligar o bot" (POST /telegram/click → passos). `null`
  // = ainda não pedidas; o POST é uma ESCRITA (abre as instruções) e por isso
  // viaja com CSRF, como todo POST desta superfície.
  const [passosBot, setPassosBot] = useState<readonly PassoBot[] | null>(null)
  const [passosAbertos, setPassosAbertos] = useState(false)
  const [passosEmVoo, setPassosEmVoo] = useState(false)
  const [passosErro, setPassosErro] = useState<string | null>(null)

  // Formulário de token.
  const [valor, setValor] = useState('')
  const [mostrarToken, setMostrarToken] = useState(false)
  const [enviando, setEnviando] = useState(false)
  const [feedback, setFeedback] = useState<FeedbackDeForm | null>(null)
  // "Trocar" (checkpoint 2/3) volta ao Passo 1 com o formulário de token aberto.
  const [trocarTokenAberto, setTrocarTokenAberto] = useState(false)
  const inputTokenRef = useRef<HTMLInputElement | null>(null)
  // Confirmação destrutiva (checkpoint 3, Avançado): 'trocar' (token) ou
  // 'desfazer' (parear). Textos exatos do contrato/section de confirmações.
  const [confirmacao, setConfirmacao] = useState<'trocar' | 'desfazer' | null>(null)

  // O fluxo do PAREAMENTO VIA PAINEL.
  const [par, setPar] = useState<EstadoDePareamentoUi>({ fase: 'ocioso' })
  const [pareado, setPareado] = useState(false)
  // Referencia para parar a sondagem no unmount / quando parear.
  const sondaParRef = useRef<number | null>(null)

  // "Agora" — ticker de 1s só para re-render (contagem do código de pareamento).
  const [agora, setAgora] = useState(() => Date.now())

  // Evita setState depois do unmount (fetch async que termina tarde).
  const vivo = useRef(true)

  const buscarToken = React.useCallback(async (): Promise<void> => {
    try {
      const dados = await apiGet<EstadoDoToken>('/token-state')
      if (vivo.current) setToken(dados)
    } catch {
      if (vivo.current) setTokenErro('não foi possível ler o estado — servidor inacessível')
    }
  }, [])

  const buscarTelegrama = React.useCallback(async (): Promise<void> => {
    try {
      const dados = await apiGet<EstadoTelegrama>('/telegram')
      if (vivo.current) {
        // O provedor ATIVO, quando o host o emitir (campo opcional; hoje não
        // vem — o default 'telegram' é o único provedor real).
        setProvider(normalizarProvider(dados.provider))
        // Guarda o estado do bot para o chip do cabeçalho (Online/Offline).
        setTelegrama(dados)
        // O bot ONLINE = token configurado E pareamento feito. Se já está
        // pareado (ex.: via CLI, ou por outra aba), o painel reflete logo
        // "Pareado" e NUNCA mostra o botão de parear.
        if (dados.online) {
          setPareado(true)
          setPar({ fase: 'pareado' })
          if (sondaParRef.current !== null) {
            window.clearInterval(sondaParRef.current)
            sondaParRef.current = null
          }
        }
      }
    } catch {
      /* o marcador fica em "verificando…"; sem ação para o user */
    }
  }, [])

  // A checagem AO VIVO de descoberta. `forcar` contorna o cache curto do
  // backend (botão "Verificar de novo"); sem `forcar`, o backend serve um
  // resultado cacheado de ~30s para não bater getMe a cada poll de ~5s.
  const buscarPrivacidade = React.useCallback(async (forcar: boolean): Promise<void> => {
    const link = forcar ? '/privacidade?forcar=true' : '/privacidade'
    try {
      const dados = await apiGet<EstadoPrivacidade>(link)
      if (vivo.current) setPrivacidade(dados)
    } catch {
      /* mantém o último resultado (honesto); sem estado inventado */
    }
  }, [])

  // A lista de AGENTES (GET /agents): a MESMA fonte do /agentes do bot — o
  // registry do host (memoria), servida pelo backend. Em falha de fetch
  // mantemos o último resultado honesto e anotamos o erro para o bloco.
  const buscarAgentes = React.useCallback(async (): Promise<void> => {
    try {
      const dados = await apiGet<EstadoAgentes>('/agents')
      if (vivo.current) {
        setAgentes(dados)
        setAgentesErro(null)
      }
    } catch {
      if (vivo.current) setAgentesErro('não foi possível carregar os agentes — servidor inacessível')
    }
  }, [])

  // Cancela um run ATIVO (POST /agents/:id/cancel com CSRF) e re-lê a lista.
  // REDUZ exposição, por isso o backend dispensa nonce — só CSRF.
  const cancelarAgente = React.useCallback(
    async (id: string): Promise<void> => {
      if (!vivo.current) return
      setCancelandoId(id)
      const r = await apiPost(`/agents/${id}/cancel`, {}, document)
      setCancelandoId(null)
      if (!vivo.current) return
      if (r.csrfIndisponivel) {
        setAgentesErro('CSRF indisponível — recarregue a página e tente de novo.')
        return
      }
      if (r.status !== 200) {
        // O run pode ter terminado entre o poll e o clique (noop {ok:false}
        // nao e erro): a mensagem so aparece em falha real de transporte.
        setAgentesErro('Não foi possível cancelar o agente. Tente de novo.')
        return
      }
      setAgentesErro(null)
      await buscarAgentes()
    },
    [buscarAgentes],
  )

  // A PROJEÇÃO do túnel (GET /state): entra no `recarregarTudo`, por isso o
  // painel re-busca ~5s e em focus/visibilitychange, como o resto. A rota
  // responde 503 {erro:'sem-estado'} quando nenhuma difusão chegou — o
  // `apiGet` lança, o catch mantém o último resultado (ou `null`) e o cartão
  // mostra "—" (nunca um "desligado" inventado).
  const buscarTunel = React.useCallback(async (): Promise<void> => {
    try {
      const dados = await apiGet<EstadoProjetado>('/state')
      if (vivo.current) setTunel(dados)
    } catch {
      /* sem estado novo: mantém o último honesto (ou "—") */
    }
  }, [])

  // Passo 1 do LIGAR/REPOR (2 etapas com nonce, o MESMO fluxo do script
  // antigo): POST /start | /reset → 200 {passo:'confirmar', nonce} → abre a
  // caixa guard-confirm; o nonce viaja OPACO no ref até o passo 2.
  const abrirTunel = React.useCallback(async (acao: 'ligar' | 'repor'): Promise<void> => {
    if (!vivo.current) return
    setTunelErro(null)
    setTunelEmVoo(true)
    try {
      const r = await apiPost(acao === 'ligar' ? '/start' : '/reset', {}, document)
      if (!vivo.current) return
      if (r.csrfIndisponivel) {
        setTunelErro('CSRF indisponível — recarregue a página e tente de novo.')
        return
      }
      const nonce = r.dados.nonce
      if (r.status === 200 && r.dados.passo === 'confirmar' && typeof nonce === 'string' && nonce.length > 0) {
        nonceTunelRef.current = nonce
        setConfirmacaoTunel(acao)
        return
      }
      // 409 {motivo} (ex.: já ligando) ou qualquer outra falha — o motivo
      // acionável do backend, quando vier, é mostrado TAL QUAL.
      setTunelErro(mensagemDeErroTunel(r))
    } finally {
      setTunelEmVoo(false)
    }
  }, [])

  // Desligar: SEM nonce (reduz exposição — CTL-024), só a confirmação.
  const desligarTunel = React.useCallback((): void => {
    setTunelErro(null)
    setConfirmacaoTunel('desligar')
  }, [])

  // Passo 2 (Confirmar da caixa): /stop para 'desligar'; /start/confirm |
  // /reset/confirm com o nonce para 'ligar'/'repor'. Ao fim, SEMPRE refresca
  // a projeção (o estado novo chega pela próxima difusão, mas o refresco
  // imediato evita ver 5s de estado velho).
  const confirmarTunel = React.useCallback(async (): Promise<void> => {
    const acao = confirmacaoTunel
    if (acao === null) return
    let r: RespostaPost
    if (acao === 'desligar') {
      r = await apiPost('/stop', {}, document)
    } else {
      const nonce = nonceTunelRef.current
      r = nonce !== null
        ? await apiPost(acao === 'ligar' ? '/start/confirm' : '/reset/confirm', { nonce }, document)
        : { status: 0, dados: {}, csrfIndisponivel: true }
    }
    nonceTunelRef.current = null
    setConfirmacaoTunel(null)
    if (!vivo.current) return
    if (r.csrfIndisponivel) {
      setTunelErro('CSRF indisponível — recarregue a página e tente de novo.')
      return
    }
    if (r.status === 200) {
      setTunelErro(null)
      await buscarTunel()
      return
    }
    setTunelErro(mensagemDeErroTunel(r))
  }, [confirmacaoTunel, buscarTunel])

  // O Confirmar do túnel, com a guarda anti-duplo-clique: desabilita no 1.º
  // clique (o `disabled` do botão) e SÓ volta quando a resposta chegar — a
  // guarda síncrona cobre o segundo clique que chega antes do re-render.
  const aoConfirmarTunel = React.useCallback((): void => {
    if (confirmandoTunel) return
    setConfirmandoTunel(true)
    void confirmarTunel().finally(() => {
      if (vivo.current) setConfirmandoTunel(false)
    })
  }, [confirmandoTunel, confirmarTunel])

  // As instruções "como ligar o bot": POST /telegram/click (com CSRF) →
  // 200 {passos:[{titulo,texto}]} → render como CHILDREN (texto puro, NUNCA
  // innerHTML). Falha → mensagem vermelha; o clique é re-tentável.
  const pedirPassosDoBot = React.useCallback(async (): Promise<void> => {
    if (!vivo.current) return
    setPassosErro(null)
    setPassosEmVoo(true)
    try {
      const r = await apiPost('/telegram/click', {}, document)
      if (!vivo.current) return
      if (r.csrfIndisponivel) {
        setPassosErro('CSRF indisponível — recarregue a página e tente de novo.')
        return
      }
      if (r.status !== 200 || !Array.isArray(r.dados.passos)) {
        setPassosErro(mensagemDeErroTunel(r))
        return
      }
      // Só passos BEM-FORMADOS (titulo/texto strings) entram no estado — um
      // item malformado do host nunca derruba o painel.
      const passos = (r.dados.passos as unknown[]).filter(
        (p): p is PassoBot =>
          p !== null && typeof p === 'object' &&
          typeof (p as PassoBot).titulo === 'string' && typeof (p as PassoBot).texto === 'string',
      )
      setPassosBot(passos)
      setPassosAbertos(true)
    } finally {
      setPassosEmVoo(false)
    }
  }, [])

  const recarregarTudo = React.useCallback(async (): Promise<void> => {
    await Promise.all([buscarToken(), buscarTelegrama(), buscarPrivacidade(false), buscarAgentes(), buscarTunel()])
  }, [buscarToken, buscarTelegrama, buscarPrivacidade, buscarAgentes, buscarTunel])

  // Sonda /pair-state a cada ~3s enquanto houver um código a aguardar (ou a
  // gerar), até o `pareado:true` chegar (o dono digitou /parear no Telegram).
  // Também reflete o pareamento feito por OUTRA via (ex.: o CLI): se ficou
  // pareado e o painel ainda mostra o botão, troca para "Pareado ✓" e para.
  const sondarPareado = React.useCallback(async (): Promise<void> => {
    if (!vivo.current) return
    let estado: EstadoPareamento
    try {
      estado = await apiGet<EstadoPareamento>('/pair-state')
    } catch {
      return // servidor inacessível — a próxima sondagem tenta de novo
    }
    if (!vivo.current) return
    if (estado.pareado) {
      setPareado(true)
      setPar({ fase: 'pareado' })
      if (sondaParRef.current !== null) {
        window.clearInterval(sondaParRef.current)
        sondaParRef.current = null
      }
      return
    }
    // Continua a aguardar: nada a mudar — a contagem regressiva já corre.
  }, [])

  // Arma a sondagem quando o fluxo está em `gerando`/`codigo`; desarma quando
  // sai ou quando o componente vive mais.
  React.useEffect(() => {
    if (par.fase === 'ocioso' || par.fase === 'pareado' || par.fase === 'expirou') return
    if (sondaParRef.current !== null) return
    sondaParRef.current = window.setInterval(() => {
      void sondarPareado()
    }, 3000)
    return () => {
      if (sondaParRef.current !== null) {
        window.clearInterval(sondaParRef.current)
        sondaParRef.current = null
      }
    }
  }, [par.fase, sondarPareado])

  // Gera UM código de pareamento (POST /pair com CSRF) e mostra-o em destaque.
  const gerarCodigo = React.useCallback(async (): Promise<void> => {
    if (!vivo.current) return
    setPar({ fase: 'gerando' })
    const r = await apiPost('/pair', {}, document)
    if (!vivo.current) return
    if (r.csrfIndisponivel) {
      setPar({ fase: 'erro', mensagem: 'CSRF indisponível — recarregue a página e tente de novo.' })
      return
    }
    if (r.status === 200) {
      const codigo = typeof r.dados.codigo === 'string' ? r.dados.codigo : ''
      const expiraEm = typeof r.dados.expiraEm === 'number' ? r.dados.expiraEm : 0
      if (codigo.length === 0 || expiraEm <= 0) {
        setPar({ fase: 'erro', mensagem: 'O servidor respondeu sem código. Tentou gerar de novo.' })
        return
      }
      setPar({ fase: 'codigo', codigo, expiraEm })
      await sondarPareado()
      return
    }
    // 409 (ja-pareado/sem-token/worker-indisponivel) ou outro erro.
    const mensagem =
      typeof r.dados.mensagem === 'string' && r.dados.mensagem.length > 0
        ? r.dados.mensagem
        : 'Não foi possível gerar o código. Tente de novo.'
    setPar({ fase: 'erro', mensagem })
    if (r.status === 409 && r.dados.erro === 'ja-pareado') {
      setPareado(true)
      await recarregarTudo()
    }
  }, [sondarPareado, recarregarTudo])

  const novoCodigo = React.useCallback((): void => {
    setPar({ fase: 'ocioso' })
  }, [])

  // Monte: marca vivo e re-busca tudo. Desmonte: marca morto.
  useEffect(() => {
    vivo.current = true
    void recarregarTudo()
    return () => {
      vivo.current = false
    }
  }, [recarregarTudo])

  // Ticker de 1s para re-render (contagem do código de pareamento).
  useEffect(() => {
    const t = window.setInterval(() => setAgora(Date.now()), 1000)
    return () => window.clearInterval(t)
  }, [])

  // Refresh automático a cada ~5s enquanto a aba estiver aberta.
  useEffect(() => {
    const t = window.setInterval(() => {
      void recarregarTudo()
    }, 5000)
    return () => window.clearInterval(t)
  }, [recarregarTudo])

  // Re-busca em focus/visibilitychange (o estado muda quando o user configura).
  useEffect(() => {
    const aoFocus = (): void => {
      void recarregarTudo()
    }
    const aoVisivel = (): void => {
      if (document.visibilityState === 'visible') void recarregarTudo()
    }
    window.addEventListener('focus', aoFocus)
    document.addEventListener('visibilitychange', aoVisivel)
    return () => {
      window.removeEventListener('focus', aoFocus)
      document.removeEventListener('visibilitychange', aoVisivel)
    }
  }, [recarregarTudo])

  const enviarToken = async (e: React.FormEvent): Promise<void> => {
    e.preventDefault()
    const bruto = valor.trim()
    if (bruto.length === 0) {
      setFeedback({ tipo: 'erro', texto: 'Digite a chave do bot antes de validar.' })
      return
    }
    setEnviando(true)
    setFeedback(null)
    const r = await apiPost('/token', { token: bruto }, document)
    setEnviando(false)
    if (!vivo.current) return

    if (r.csrfIndisponivel) {
      setFeedback({ tipo: 'erro', texto: 'CSRF indisponível — recarregue a página e tente de novo.' })
      return
    }

    switch (r.status) {
      case 200: {
        const handle = typeof r.dados.handle === 'string' && r.dados.handle.length > 0 ? r.dados.handle : null
        setValor('')
        setMostrarToken(false)
        setTrocarTokenAberto(false)
        setFeedback({ tipo: 'ok', texto: handle ? `Configurado ✓ @${handle}` : 'Configurado ✓' })
        await recarregarTudo()
        // Token recém-aplicado: força a checagem AO VIVO de descoberta (contorna
        // o cache de ~30s que podia ainda guardar o "sem token/não configurado").
        void buscarPrivacidade(true)
        break
      }
      case 400: {
        const erro = r.dados.erro
        setFeedback({
          tipo: 'erro',
          texto:
            erro === 'formato-invalido'
              ? rotulos.formatoInvalido
              : 'Token vazio — cole a chave antes de validar.',
        })
        break
      }
      case 409: {
        const aviso = typeof r.dados.aviso === 'string' ? r.dados.aviso : ''
        setFeedback({
          tipo: 'aviso',
          texto:
            aviso.length > 0
              ? aviso
              : rotulos.envManda,
        })
        await recarregarTudo()
        break
      }
      case 422: {
        setFeedback({
          tipo: 'erro',
          texto: rotulos.tokenRecusado,
        })
        break
      }
      default: {
        setFeedback({
          tipo: 'erro',
          texto:
            r.status === 0
              ? 'Sem ligação ao Telegram. Verifica a rede e tenta de novo.'
              : 'O servidor não respondeu — recarregue a página e tente de novo.',
        })
      }
    }
  }

  // Ação "Revisar token": limpa o erro e foca o campo para o dono corrigir.
  const revisarToken = React.useCallback((): void => {
    setFeedback(null)
    setTrocarTokenAberto(true)
    // Focus no render seguinte.
    requestAnimationFrame(() => inputTokenRef.current?.focus())
  }, [])

  // "Trocar" (collapsed) / "Trocar o token" (Avançado): volta ao Passo 1 com o
  // formulário de token aberto.
  const abrirTrocar = React.useCallback((): void => {
    setConfirmacao(null)
    setFeedback(null)
    setTrocarTokenAberto(true)
  }, [])

  // Confirma a ação destrutiva do Avançado. Para "trocar", volta ao formulário
  // do Passo 1. Para "desfazer", o parear só se reabre com `--reset-pairing` na
  // MÁQUINA (PAIR-008) — o painel não tem rota de desfazer (o texto guia, não
  // força); a confirmação fecha e o copy já disse o que acontece. Em AMBOS os
  // casos, após confirmar, o painel dispara um refresh COMPLETO do estado
  // sincronizado + uma checagem AO VIVO de descoberta (getMe FORÇADO, que
  // contorna o cache de ~30s do backend) — responde "o bot ainda existe?" com
  // checagem real, e reflete já a nova realidade (ex.: token trocado / bot
  // removido) sem esperar o poll seguinte.
  const confirmar = React.useCallback((): void => {
    const tipo = confirmacao
    if (tipo === null) return
    if (tipo === 'trocar') {
      abrirTrocar()
    } else {
      // 'desfazer': sem rota no painel — fecha a confirmação (orientação honesta).
      setConfirmacao(null)
    }
    void recarregarTudo()
    void buscarPrivacidade(true)
  }, [confirmacao, abrirTrocar, recarregarTudo, buscarPrivacidade])

  const rotulos = rotulosDoProvider(provider)
  const chip = chipDoBot(token, telegrama, provider)
  const configurado = token?.configurado === true
  const handleChave = token?.handle
  const rotuloHandle = handleChave && handleChave.length > 0 ? `@${handleChave}` : 'o bot'
  const passo1Aberto = !configurado || trocarTokenAberto

  // --- Passo 1 ✻ formulário de token (aberto quando sem token ou ao "Trocar") ---
  const cartaoToken = h('div', { className: 'guard-card' },
    h(CabecalhoPasso, { indice: 1, titulo: 'Criar o bot', concluido: configurado }),
    h(CartaoTokenForm, {
      valor,
      mostrarToken,
      enviando,
      feedback,
      inputRef: inputTokenRef,
      rotulos,
      aoMudar: setValor,
      aoAlternarMostrar: () => setMostrarToken((v) => !v),
      aoEnviar: enviarToken,
      aoRevisar: revisarToken,
    }),
    h(Detalhes, { resumo: 'Como criar o bot do zero' }, h(BotaoBotFatherDetalhado, { rotulos })),
    !configurado ? paragrafo('guard-step-hint', 'Depois disto, avanças para o Passo 2: parear.') : null,
  )

  // --- Passo 1 ✻ colapsado (concluído) quando configurado ---
  const passo1Concluido = configurado && !trocarTokenAberto
    ? h(PassoConcluido, {
        resumo: `Bot ${rotuloHandle} conectado`,
        aoAcao: abrirTrocar,
        rotuloAcao: 'Trocar',
      })
    : null

  // --- Passo 2 ✻ Parear (configurado e NÃO pareado) ---
  const passo2 = configurado && !pareado
    ? h('div', { className: 'guard-card' },
        h(CabecalhoPasso, { indice: 2, titulo: 'Parear', concluido: false }),
        h(CartaoParear, {
          handle: handleChave ?? undefined,
          estado: par,
          pareado,
          agora,
          rotulos,
          aoGerar: () => void gerarCodigo(),
          aoNovoCodigo: () => novoCodigo(),
        }),
      )
    : null

  // --- Passo 2 ✻ "✓ Pareado" (linha fina) quando pareado ---
  const passo2Concluido = pareado
    ? h('div', { className: 'guard-card guard-step-done' },
        h('span', { className: 'guard-card-title' },
          h('span', { className: 'guard-step-check', 'aria-hidden': 'true' }, '✓'),
          'Pareado',
        ),
        paragrafo('guard-intro', 'Pareado! Este painel agora controla o bot. Vai ao Passo 3 para começar.'),
      )
    : null

  // --- Passo 3 ✻ Usar (pareado) ---
  const passo3 = pareado
    ? h('div', { className: 'guard-card' },
        h(CabecalhoPasso, { indice: 3, titulo: 'Usar', concluido: false }),
        // Comandos essenciais — 3 linhas, uma ideia cada.
        h('span', { className: 'guard-block-title' }, 'Comandos essenciais'),
        h('ul', { className: 'guard-steps' },
          COMANDOS_ESSENCIAIS.map((bloco, i) =>
            h('li', { className: 'guard-step', key: i }, h(LinhaDeComando, { bloco })),
          ),
        ),
        // Avançado (dobrado): trocar token / desfazer parear / todos os comandos.
        h(Detalhes, { resumo: 'Avançado' },
          h('ul', { className: 'guard-links' },
            h('li', null,
              h('button', { type: 'button', className: 'guard-link', onClick: () => setConfirmacao('trocar') },
                'Trocar o token'),
            ),
            h('li', null,
              h('button', { type: 'button', className: 'guard-link', onClick: () => setConfirmacao('desfazer') },
                'Desfazer parear'),
            ),
          ),
          h('span', { className: 'guard-block-title' }, 'Ver todos os comandos'),
          h('ul', { className: 'guard-steps' },
            COMANDOS_DE_USO.map((bloco, i) =>
              h('li', { className: 'guard-step', key: i }, h(LinhaDeComando, { bloco })),
            ),
          ),
        ),
        // E minha conversa? (privacidade, dobrada) — migrada do bloco solto.
        h(CartaoPrivacidadeCkpt3, {
          estado: privacidade,
          rotulos,
          aoVerificar: () => void buscarPrivacidade(true),
        }),
      )
    : null

  // --- Confirmação destrutiva (Avançado) --------------------------------
  const caixaConfirmacao = confirmacao !== null
    ? CartaoConfirmacao({
        tipo: confirmacao,
        aoConfirmar: confirmar,
        aoCancelar: () => setConfirmacao(null),
      })
    : null

  // --- Cartão TÚNEL (o controle da home, agora aqui) ---------------------
  const cartaoTunel = h(CartaoTunel, {
    tunel,
    agora,
    erro: tunelErro,
    emVoo: tunelEmVoo,
    aoLigar: () => void abrirTunel('ligar'),
    aoDesligar: desligarTunel,
    aoRepor: () => void abrirTunel('repor'),
    passos: passosBot,
    passosAbertos,
    passosEmVoo,
    passosErro,
    aoPassos: () => void pedirPassosDoBot(),
    aoAlternarPassos: setPassosAbertos,
  })

  // A caixa guard-confirm do túnel (logo abaixo do cartão). O Cancelar
  // descarta o nonce pendente com a confirmação.
  const caixaConfirmacaoTunel = confirmacaoTunel !== null
    ? h(CartaoConfirmacaoTunel, {
        acao: confirmacaoTunel,
        confirmando: confirmandoTunel,
        aoConfirmar: aoConfirmarTunel,
        aoCancelar: () => {
          if (confirmandoTunel) return
          nonceTunelRef.current = null
          setConfirmacaoTunel(null)
        },
      })
    : null

  // --- Bloco de AGENTES (abaixo da trilha — sempre visível) -------------
  const blocoAgentes = h(CartaoAgentes, {
    estado: agentes,
    erro: agentesErro,
    cancelandoId,
    agora,
    aoCancelar: (id) => void cancelarAgente(id),
  })

  return h('div', { className: 'guard-section' },
    // --- Bloco de marca (logo do plugin) --------------------------------
    h('div', { className: 'guard-brand' },
      h('img', { className: 'guard-logo', src: logoUrl, alt: 'dsh-guard-messenger' }),
    ),
    // --- Título + chip de estado ----------------------------------------
    h('div', { style: { display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' } },
      h('h2', { className: 'guard-title', style: { margin: 0 } }, 'Remote Access'),
      h(Chip, { chip }),
    ),
    paragrafo('guard-intro', rotulos.acessoIntro),
    tokenErro ? paragrafo('guard-error', tokenErro) : null,

    // --- A TRILHA (só o passo atual aberto) -----------------------------
    passo1Aberto ? cartaoToken : passo1Concluido,
    passo2,
    passo2Concluido,
    passo3,
    caixaConfirmacao,

    // --- TÚNEL + instruções do bot (o ex-bloco da home) -----------------
    cartaoTunel,
    caixaConfirmacaoTunel,
    blocoAgentes,
  )
}

/**
 * O formulário do token (Passo 1). Um CTA primário ("Salvar bot"); erro com a
 * ação "Revisar token" que limpa o feedback e foca o campo.
 */
function CartaoTokenForm(props: {
  readonly valor: string
  readonly mostrarToken: boolean
  readonly enviando: boolean
  readonly feedback: FeedbackDeForm | null
  readonly inputRef: React.RefObject<HTMLInputElement | null>
  readonly rotulos: RotulosDoProvider
  readonly aoMudar: (v: string) => void
  readonly aoAlternarMostrar: () => void
  readonly aoEnviar: (e: React.FormEvent) => void
  readonly aoRevisar: () => void
}): React.ReactNode {
  const mostraErro = props.feedback !== null && props.feedback.tipo === 'erro'
  return h('form', { className: 'guard-field', onSubmit: props.aoEnviar },
    paragrafo('guard-intro', props.rotulos.coleToken),
    h('label', { className: 'guard-field-label', htmlFor: 'guard-token-input' }, props.rotulos.rotuloCampoToken),
    h('div', { className: 'guard-input-wrap' },
      h('input', {
        id: 'guard-token-input',
        className: 'guard-input',
        ref: props.inputRef,
        type: props.mostrarToken ? 'text' : 'password',
        value: props.valor,
        autoComplete: 'off',
        spellCheck: false,
        placeholder: props.rotulos.tokenPlaceholder,
        onChange: (e: React.ChangeEvent<HTMLInputElement>) => props.aoMudar(e.target.value),
      }),
      h('button', {
        type: 'button',
        className: 'guard-toggle',
        'aria-label': props.mostrarToken ? 'Ocultar token' : 'Mostrar token',
        onClick: props.aoAlternarMostrar,
      }, props.mostrarToken ? '🙈' : '👁'),
    ),
    h('div', { className: 'guard-actions' },
      h('button', { type: 'submit', className: 'guard-btn guard-btn-primary', disabled: props.enviando },
        props.enviando ? props.rotulos.conectando : 'Salvar bot'),
      mostraErro
        ? h('button', { type: 'button', className: 'guard-btn guard-btn-outline', onClick: props.aoRevisar },
            'Revisar token')
        : null,
    ),
    props.feedback
      ? h('p', {
          className:
            props.feedback.tipo === 'ok' ? 'guard-success-text' : props.feedback.tipo === 'erro' ? 'guard-error' : 'guard-notice',
        }, props.feedback.texto)
      : null,
  )
}

/**
 * A confirmação destrutiva do Avançado (textos EXATOS do contrato). Dois tipos:
 * 'trocar' (token) e 'desfazer' (parear), cada um com [ação][Cancelar].
 */
function CartaoConfirmacao({
  tipo,
  aoConfirmar,
  aoCancelar,
}: {
  readonly tipo: 'trocar' | 'desfazer'
  readonly aoConfirmar: () => void
  readonly aoCancelar: () => void
}): React.ReactNode {
  const texto =
    tipo === 'trocar'
      ? 'Trocar o token desliga temporariamente o bot. Continuar?'
      : 'Desfazer o parear fecha o teu acesso pelo bot a partir deste painel. Não dá para desfazer sem parear de novo. O painel vai re-verificar o estado do bot. Continuar?'
  const rotulo = tipo === 'trocar' ? 'Trocar token' : 'Desfazer parear'
  return h('div', { className: 'guard-card guard-confirm' },
    paragrafo('guard-error', texto),
    h('div', { className: 'guard-actions' },
      h('button', { type: 'button', className: 'guard-btn guard-btn-primary', onClick: aoConfirmar }, rotulo),
      h('button', { type: 'button', className: 'guard-btn guard-btn-outline', onClick: aoCancelar }, 'Cancelar'),
    ),
  )
}

/* ========================================================================== */
/* apply — regista as contribuições e injeta o CSS                            */
/* ========================================================================== */

/**
 * Corpo do plugin client. Injeta o CSS do painel e regista a ÚNICA entrada de
 * slot: a aba `settings.section` "Remote Access" (acessível pelo rail do modal
 * de settings padrão do shell).
 * @param ctx - contexto raiz Cordis do browser (injeta `slots`).
 */
export function apply(ctx: {
  slots: {
    inject(key: string, cb: () => unknown): unknown
    register(options: unknown, component: unknown): unknown
  }
}): void {
  // O CSS do painel (guard-panel.css) entra no DOM aqui, UMA vez, antes de
  // qualquer registo renderizar o cartão.
  asegurarCss(document)

  // Aba no modal de settings (slot declarado pelo ui-settings). O botão do
  // rodapé da sidebar (`sidebar.footer.action`) foi REMOVIDO — o acesso é pelo
  // settings padrão do shell, que mostra esta aba no rail.
  ctx.slots.inject('settings.section', () =>
    ctx.slots.register(
      {
        name: 'settings.section',
        id: 'telegram-guard',
        order: 99,
        label: 'Remote Access',
        registrant: 'dsh-guard-messenger',
      },
      TelegramGuardSection,
    ),
  )
}